\begin{theorem}\label{thm:main}
If $N\equiv2\pmod4$, then for every fixed $M\in\mathbb R^2$ the
product $A'B_M$ is constant as the initial vertex varies through
the fixed-caustic family \eqref{eq:conics}.
\end{theorem}

\begin{proposition}\label{prop:six}
For the six-periodic family with
$\lambda=a^2b^2/(a+b)^2$,
\begin{equation}\label{eq:six}
 A'B_M=ab(a+2b)(2a+b)
       \left(1+\frac{|M|^2}{(a+b)^2}\right).
\end{equation}
\end{proposition}
